import java.util.Comparator;

interface HeapFactory {
    AbstractHeap forIntRange(int[] arr, int from);
    <T> Heap<T> forObjectRange(T[] arr, int from, int to, Comparator<T> cmp);
}
import java.util.Comparator;

final class SortContext implements HeapFactory {

    @Override
    public AbstractHeap forIntRange(int[] arr, int from) {
        return new RangeHeap(arr, from);
    }

    @Override
    public <T> Heap<T> forObjectRange(T[] arr, int from, int to, Comparator<T> cmp) {
        return new ObjectRangeHeap<>(arr, from, to, cmp);
    }
}
import java.util.Comparator;

public class HeapSort {

    private static final HeapFactory FACTORY = new SortContext();

    public static void heapSort(int[] arr) {
        heapSort(arr, 0, arr.length);
    }

    public static void heapSort(int[] arr, int from, int to) {
        if (from < 0 || to > arr.length || from > to)
            throw new IllegalArgumentException(
                "Invalid range [" + from + ", " + to + ") for array of length " + arr.length);
        FACTORY.forIntRange(arr, from).sort(to - from);
    }

    public static <T> void heapSort(T[] arr, Comparator<T> cmp) {
        heapSort(arr, 0, arr.length, cmp);
    }

    public static <T> void heapSort(T[] arr, int from, int to, Comparator<T> cmp) {
        if (from < 0 || to > arr.length || from > to)
            throw new IllegalArgumentException(
                "Invalid range [" + from + ", " + to + ") for array of length " + arr.length);
        FACTORY.forObjectRange(arr, from, to, cmp).sort();
    }
}
abstract class AbstractHeap {

    void sort(int n) {
        build(n);
        for (int i = n - 1; i > 0; i--) {
            swap(0, i);
            siftDown(0, i);
        }
    }

    private void build(int n) {
        for (int i = n / 2 - 1; i >= 0; i--)
            siftDown(i, n);
    }

    private void siftDown(int i, int n) {
        int largest = i;
        int l = 2 * i + 1;
        int r = 2 * i + 2;
        if (l < n && isGreater(l, largest))
            largest = l;
        if (r < n && isGreater(r, largest))
            largest = r;
        if (largest != i) {
            swap(i, largest);
            siftDown(largest, n);
        }
    }

    protected abstract boolean isGreater(int i, int j);
    protected abstract void swap(int i, int j);
}
class RangeHeap extends AbstractHeap {
    private final int[] arr;
    private final int from;

    RangeHeap(int[] arr, int from) {
        this.arr = arr;
        this.from = from;
    }

    @Override
    protected boolean isGreater(int i, int j) {
        return arr[from + i] > arr[from + j];
    }

    @Override
    protected void swap(int i, int j) {
        int temp = arr[from + i];
        arr[from + i] = arr[from + j];
        arr[from + j] = temp;
    }
}
import java.util.Comparator;

class ObjectRangeHeap<T> extends AbstractHeap implements Heap<T> {
    private final T[] arr;
    private final int from;
    private final int size;
    private final Comparator<T> cmp;

    ObjectRangeHeap(T[] arr, int from, int to, Comparator<T> cmp) {
        this.arr = arr;
        this.from = from;
        this.size = to - from;
        this.cmp = cmp;
    }

    @Override
    public void sort() {
        sort(size);
    }

    @Override
    protected boolean isGreater(int i, int j) {
        return cmp.compare(arr[from + i], arr[from + j]) > 0;
    }

    @Override
    protected void swap(int i, int j) {
        T temp = arr[from + i];
        arr[from + i] = arr[from + j];
        arr[from + j] = temp;
    }
}

